mapper.select:
SELECT ID, IMPORT_MODE, STATUS, PARK_ID, PARK_NAME, DISPATCHER_PARK_ID, DISPATCHER_PARK_NAME, TOTAL_COUNT, SUCCESS_COUNT, SKIP_COUNT, CONFLICT_COUNT, FAIL_COUNT, CONSUME, PARAMS_JSON, REMARK, START_TIME, END_TIME, CREATE_TIME, UPDATE_TIME, OPT_USER FROM SMT_ISC_CARD_IMPORT_BATCH
AND PARK_ID IN
#{parkId}
AND PARK_ID = #{query.parkId}
AND IMPORT_MODE = #{query.mode}
AND STATUS = #{query.status}
AND TO_DATE(TO_CHAR(CREATE_TIME, 'YYYY-MM-DD'),'YYYY-MM-DD') >= TO_DATE(#{query.startTime,jdbcType=DATE}, 'yyyy-MM-dd')
AND TO_DATE(TO_CHAR(CREATE_TIME, 'YYYY-MM-DD'),'YYYY-MM-DD') <= TO_DATE(#{query.endTime,jdbcType=DATE}, 'yyyy-MM-dd')
ORDER BY CREATE_TIME DESC, ID DESC
